import fs from 'node:fs/promises';import{send,asset,db,reviewed}from'./reply-runtime-20261015.mjs';
const dir='artifacts/reply-review-20261019-weekend',plans=JSON.parse(await fs.readFile(dir+'/1340-plans.json')),context=JSON.parse(await fs.readFile(dir+'/latest-reply-check.json')).rows,results=[];
for(const p of plans){try{const r=await send({...p,from:p.from_number,followup_key:'20261019-1340',media_urls:p.card?[await asset(p.city)]:[],note:'Owner-authorized contextual reply; no price or booking commitment.'});if(r.state!=='accepted')throw Error('Ambiguous receipt');results.push({name:p.name,state:'accepted',sid:r.result.sid,card:p.card});for(const t of context.find(r=>r.contact.id===p.id).thread.filter(t=>t.direction==='inbound'&&t.id!==p.latest&&!t.metadata?.partnership_review))await reviewed(t.id,'Current enquiry answered in owner-approved reply.',{provider_receipt:r.result.sid});}catch(e){results.push({name:p.name,state:'held',error:String(e)});}await fs.writeFile(dir+'/1340-results.json',JSON.stringify(results,null,2));}
for(const name of ['DENNIS PITINO','JANET SCOTT','Peggy MacIsaac','Debbie Taylor','MUSENNA UCAR','MARINA ANTON JOSEPH','ARLENE DI IULIO','LISA MAH']){const r=context.find(r=>r.contact.name===name);if(!r)continue;const[last]=await db('market_touches',{contact_id:'eq.'+r.contact.id,order:'created_at.desc,id.desc',limit:'1'});if(last.id!==r.thread[0].id)continue;await reviewed(last.id,'Reviewed acknowledgement, reaction, decline or retired contact. No further message needed; no automatic chase.');await db('market_contacts',{id:'eq.'+r.contact.id},'PATCH',{sequence_paused:true,sequence_paused_reason:name==='Debbie Taylor'?'retired_contact':'human_managed_relationship',next_follow_up:null});}
const sales={};for(const phone of ['+14168566474','+16472018834']){sales[phone]={sms:await db('sms_messages',{or:`(from_number.eq.${phone},to_number.eq.${phone})`,order:'created_at.desc',limit:'30'}),leads:await db('crm_leads',{deleted:'eq.false',or:`(data->>phone.eq.${phone},data->>phone.eq.${phone.replace(/^\+1/,'')})`})};}await fs.writeFile(dir+'/1340-sales-context.json',JSON.stringify(sales,null,2));console.log(JSON.stringify(results));
